import java.util.*;

interface Pengirim {
    String kirim(String pesan);
}

class EmailPengirim implements Pengirim {
    public String kirim(String pesan) {
        return "Email: " + pesan;
    }
}

class SmsPengirim implements Pengirim {
    public String kirim(String pesan) {
        return "SMS: " + pesan;
    }
}

class Notifikasi {
    private Pengirim pengirim;

    Notifikasi(Pengirim pengirim) {
        this.pengirim = pengirim;
    }

    String beri(String pesan) {
        return pengirim.kirim(pesan);
    }
}

public class MainB {
    public static void main(String[] args) {
        System.out.println(new Notifikasi(new EmailPengirim()).beri("Halo"));
    }
}

